-- Hyprland config — Lua format (0.55+).
-- Converted from hyprland.conf; see https://wiki.hypr.land/Configuring/
--
-- Split across files via require(). monitors/workspaces are regenerated by
-- hypr-monitor on every hotplug; colors by theme-apply. Do not edit those.

------------------
---- MONITORS ----
------------------

-- monitors.lua and workspaces.lua do not exist until hypr-monitor first runs.
-- hyprlang's `source` warned and carried on when a file was missing, but Lua's
-- require is fatal and would abort the rest of this file, leaving a fresh
-- machine with no binds at all. Tolerate absent; still surface a generated file
-- that exists but is malformed, rather than silently skipping it.
local function require_generated(name)
    local ok, err = pcall(require, name)
    if ok or tostring(err):match("^module '" .. name .. "' not found") then
        return
    end
    error(err, 0)
end

require_generated("monitors")
require_generated("workspaces")
local clr = require("colors")


