-- Scratchpad. Native dispatchers, not `hyprctl dispatch` — under a Lua config the
-- legacy string form is rejected outright. The second bind on each key nudges the
-- waybar scratchpad/tray indicators, which have no event to hook.
local refreshSpecialWaybar = hl.dsp.exec_cmd("pkill -RTMIN+9 waybar; pkill -RTMIN+10 waybar")

hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special("󰏫"))
hl.bind(mainMod .. " + S", refreshSpecialWaybar)
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:󰏫" }))
hl.bind(mainMod .. " + SHIFT + S", refreshSpecialWaybar)

