hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Move project (all windows + name) to next/prev monitor's empty slot
hl.bind(mainMod .. " + CTRL + right", hl.dsp.exec_cmd("~/.local/bin/hypr-move-project next"))
hl.bind(mainMod .. " + CTRL + left",  hl.dsp.exec_cmd("~/.local/bin/hypr-move-project prev"))

-- --- Named workspaces (rofi) ---
local wsMgr = "~/.local/bin/hypr-dynamic-workspaces"

hl.bind(mainMod .. " + Z",         hl.dsp.exec_cmd(wsMgr .. " --workspace-switcher"))
hl.bind(mainMod .. " + SHIFT + Z", hl.dsp.exec_cmd(wsMgr .. " --move-window"))
hl.bind(mainMod .. " + BackSpace", hl.dsp.exec_cmd(wsMgr .. " --delete-current-workspace"))
hl.bind(mainMod .. " + ALT + space", hl.dsp.exec_cmd(wsMgr .. " --window-switcher"))

-- Sequential workspace navigation (desktop-contained, non-empty only)
hl.bind(mainMod .. " + Tab",         hl.dsp.exec_cmd("~/.local/bin/hypr-tab-nonempty"))
hl.bind(mainMod .. " + SHIFT + Tab", hl.dsp.exec_cmd("~/.local/bin/hypr-tab-nonempty prev"))

-- Resize submap (SUPER+A to enter, hjkl to resize, Esc to exit)
hl.bind(mainMod .. " + A", hl.dsp.submap("resize"))
hl.define_submap("resize", "reset", function()
    -- relative = true, else x/y are treated as an absolute target size
    hl.bind("h", hl.dsp.window.resize({ x = -10, y = 0,   relative = true }), { repeating = true })
    hl.bind("l", hl.dsp.window.resize({ x = 10,  y = 0,   relative = true }), { repeating = true })
    hl.bind("k", hl.dsp.window.resize({ x = 0,   y = -10, relative = true }), { repeating = true })
    hl.bind("j", hl.dsp.window.resize({ x = 0,   y = 10,  relative = true }), { repeating = true })
    hl.bind("escape",   hl.dsp.submap("reset"))
    hl.bind("catchall", hl.dsp.submap("reset"))
end)

-- Volume and brightness (SwayOSD, with a partial fallback)
--
-- The `|| ...` fallbacks only cover SwayOSD being *absent*. swayosd-client
-- exits non-zero when nothing owns the bus name, but exits 0 when a server
-- answers and refuses the call -- which is what a server still running a
-- binary that an upgrade deleted does, so these keys go silently dead until it
-- restarts. `make sync` now handles that; see ISSUES.md.
--
-- Do not "fix" this by calling busctl with a literal signature here: the
-- signature is what moved in swayosd 0.3.1 -> 0.3.2, so pinning it just
-- re-breaks on the next bump. Probing the server costs more than the keypress.
hl.bind("XF86AudioRaiseVolume",
    hl.dsp.exec_cmd("swayosd-client --output-volume raise 2>/dev/null || wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"),
    { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume",
    hl.dsp.exec_cmd("swayosd-client --output-volume lower 2>/dev/null || wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMute",
    hl.dsp.exec_cmd("swayosd-client --output-volume mute-toggle 2>/dev/null || wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),
    { locked = true, repeating = true })
hl.bind("XF86AudioMicMute",
    hl.dsp.exec_cmd("swayosd-client --input-volume mute-toggle 2>/dev/null || wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
    { locked = true, repeating = true })

-- Brightness (see the note above)
hl.bind("XF86MonBrightnessUp",
    hl.dsp.exec_cmd("swayosd-client --brightness raise 2>/dev/null || brightnessctl -e4 -n2 set 5%+"),
    { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown",
    hl.dsp.exec_cmd("swayosd-client --brightness lower 2>/dev/null || brightnessctl -e4 -n2 set 5%-"),
    { locked = true, repeating = true })

-- Requires playerctl
hl.bind("XF86AudioNext",  hl.dsp.exec_cmd("playerctl next"),       { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay",  hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev",  hl.dsp.exec_cmd("playerctl previous"),   { locked = true })

-- Calculator key: qalc in a new tmux pane if focused terminal has tmux, else floating kitty
hl.bind("XF86Calculator", hl.dsp.exec_cmd("~/.local/bin/hypr-qalc"))


