hl.window_rule({
    -- Ignore maximize requests from all apps.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})

-- Picture-in-Picture
hl.window_rule({
    name  = "pip-float",
    match = { title = [[^([Pp]icture[-\s]?[Ii]n[-\s]?[Pp]icture)$]] },

    float             = true,
    pin               = true,
    keep_aspect_ratio = true,
    size              = "25% 25%",
    move              = "73% 72%",
})

-- Inhibit idle when fullscreen (browsers, media players)
hl.window_rule({
    name  = "idle-inhibit-fullscreen",
    match = {
        fullscreen = true,
        class      = "^(firefox-developer-edition|firefox|microsoft-edge.*|[Gg]oogle-chrome|brave-browser|mpv|vlc|celluloid)$",
    },

    suppress_event = "idle",
})

-- Float common dialogs
hl.window_rule({
    name  = "float-dialogs",
    match = { class = "^(nm-connection-editor|org.gnome.Calculator|xdg-desktop-portal-gtk)$" },

    float = true,
})

hl.window_rule({
    name  = "float-file-dialogs",
    match = { title = "^(Open File|Save File|Save As|Confirm|File Upload)$" },

    float = true,
})

-- Floating TUI apps (nmtui, btop, etc.)
hl.window_rule({
    name  = "float-tui",
    match = { class = "^(floating-tui)$" },

    float  = true,
    size   = "800 600",
    center = true,
})

-- TUI popup menus
hl.window_rule({
    name  = "wallpaper-popup",
    match = { class = "^(hypr-wallpaper-menu)$" },

    float  = true,
    size   = "460 420",
    center = true,
})

-- Thunderbird — float compose/reply windows, keep main tiled
hl.window_rule({
    name  = "thunderbird-compose-float",
    match = {
        class = [[^(org\.mozilla\.Thunderbird)$]],
        title = "^(Write:|Re:|Fwd:)",
    },

    float  = true,
    size   = "800 600",
    center = true,
})

-- Thunderbird/Zotero — prevent focus-stealing when hidden in tray workspace
hl.window_rule({
    name  = "tray-apps-no-activate",
    match = { class = [[^(org\.mozilla\.Thunderbird|Zotero)$]] },

    suppress_event = "activate",
})


